        int size = 0;
        while (i < index + len) {
            char ch = str.charAt(i++);
            if (ch <= 0x7F) {
                size++;
            } else if (ch <= 0x7FF) {
                size += 2;
            } else if ((ch & 0xF800) == 0xD800) {
                System.err.println("Illegal codepoint: surrogate pairs are not supported");
                return -1;
            } else if (ch <= 0xFFFF) {
                size += 3;
            } else if ((ch & 0xFFFF) == 0xFFFF) {
                System.err.println("Illegal codepoint: codepoint overflow");
                return -1;
            } else if (ch <= 0x10FFFF) {
